class Solution {
public:
    long long getDescentPeriods(vector<int>& prices) {
        long long total = 0;
        int run = 0;
        int n = (int)prices.size();
        for (int i = 0; i < n; i++) {
            if (i > 0 && prices[i] == prices[i - 1] - 1) {
                run++;
            } else {
                run = 1;
            }
            total += run;
        }
        return total;
    }
};
